<template>
  <div class="market-page">
    <van-tabs v-model="activeTab" animated swipeable>
      <van-tab title="自选">
        <MarketList :data="favoriteList" :loading="loading" @toggle-favorite="toggleFavorite" />
      </van-tab>
      <van-tab title="全部">
        <MarketList :data="allList" :loading="loading" @toggle-favorite="toggleFavorite" />
      </van-tab>
      <van-tab v-for="zone in dynamicZones" :key="zone.id" :title="zone.name">
        <MarketList :data="zone.list" :loading="loading" @toggle-favorite="toggleFavorite" />
      </van-tab>
    </van-tabs>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'
import MarketList from './components/MarketList.vue'
import { getWsUrl, WS_KEYS } from '@/utils/websocketUrls'
import { connect } from '@/utils/websocketManager'

const FAVORITES_KEY = 'market_favorites'

export default {
  name: 'Market',
  components: { MarketList },
  data() {
    return {
      activeTab: 1, // 默认显示"全部"
      allList: [],
      dynamicZones: [], // 后端动态配置的分区
      favorites: [], // 自选币对 ID 列表
      wsConnection: null,
      loading: true
    }
  },
  computed: {
    ...mapGetters(['partnerId', 'partnerNo']),
    favoriteList() {
      return this.allList.filter(item =>
        this.favorites.includes(item.symbol || item.tradeName)
      )
    }
  },
  mounted() {
    this.loadFavorites()
    this.fetchZoneList()
    this.fetchAllList()
    this.initWebSocket()
  },
  beforeDestroy() {
    if (this.wsConnection) {
      this.wsConnection.close()
    }
  },
  methods: {
    // 加载本地自选
    loadFavorites() {
      try {
        const saved = localStorage.getItem(FAVORITES_KEY)
        this.favorites = saved ? JSON.parse(saved) : []
      } catch {
        this.favorites = []
      }
    },
    // 保存自选
    saveFavorites() {
      localStorage.setItem(FAVORITES_KEY, JSON.stringify(this.favorites))
    },
    // 切换自选
    toggleFavorite(symbol) {
      const idx = this.favorites.indexOf(symbol)
      if (idx > -1) {
        this.favorites.splice(idx, 1)
      } else {
        this.favorites.push(symbol)
      }
      this.saveFavorites()
    },
    // 获取分区列表（后端动态配置）
    fetchZoneList() {
      this.$api.zoneList({ partnerId: this.partnerId }).then(res => {
        if (res.data && Array.isArray(res.data)) {
          this.dynamicZones = res.data.map(zone => ({
            id: zone.id || zone.zoneCode,
            name: zone.name || zone.zoneName,
            list: []
          }))
          // 获取每个分区的币对列表
          this.dynamicZones.forEach(zone => {
            this.fetchZoneData(zone)
          })
        }
      }).catch(() => {
        // 降级：使用默认分区
        this.dynamicZones = [
          { id: 'main', name: '主板区', list: [] },
          { id: 'rwa', name: 'RWA区', list: [] }
        ]
      })
    },
    // 获取分区数据
    fetchZoneData(zone) {
      this.$api.zoneMarketList({
        partnerNo: this.partnerNo,
        zoneCode: zone.id
      }).then(res => {
        zone.list = res.data || []
      }).catch(() => {
        zone.list = []
      })
    },
    // 获取全部币对列表
    fetchAllList() {
      this.loading = true
      this.$api.homeRanking({
        partnerNo: this.partnerNo,
        type: 'ALL',
        partnerId: this.partnerId
      }).then(res => {
        this.allList = res.data || []
        this.loading = false
      }).catch(() => {
        this.allList = []
        this.loading = false
      })
    },
    // WebSocket 实时价格更新
    initWebSocket() {
      const wsUrl = getWsUrl(WS_KEYS.MARKET)
      if (!wsUrl) return

      this.wsConnection = connect(wsUrl, (data) => {
        if (data && data.symbol) {
          // 更新全部列表中的价格
          const idx = this.allList.findIndex(item => item.symbol === data.symbol)
          if (idx > -1) {
            this.$set(this.allList, idx, { ...this.allList[idx], ...data })
          }
          // 更新分区列表中的价格
          this.dynamicZones.forEach(zone => {
            const zIdx = zone.list.findIndex(item => item.symbol === data.symbol)
            if (zIdx > -1) {
              this.$set(zone.list, zIdx, { ...zone.list[zIdx], ...data })
            }
          })
        }
      })
    }
  }
}
</script>

