      } else {
        this.favorites.push(symbol)
      }
      this.saveFavorites()
    },
    fetchZoneList() {
      this.$api.zoneList({ partnerId: this.partnerId }).then(res => {
        if (res.data && Array.isArray(res.data)) {
          this.dynamicZones = res.data.map(zone => ({
            id: zone.id || zone.zoneCode,
            name: zone.name || zone.zoneName,
            list: []
          }))
          this.dynamicZones.forEach(zone => {
            this.fetchZoneData(zone)
          })
        }
      }).catch(() => {
        this.dynamicZones = [
          { id: 'main', name: '主板区', list: [] },
          { id: 'rwa', name: 'RWA区', list: [] }
        ]
      })
    },
    fetchZoneData(zone) {
      this.$api.zoneMarketList({
        partnerNo: this.partnerNo,
        zoneCode: zone.id
      }).then(res => {
        zone.list = res.data || []
      }).catch(() => {
        zone.list = []
      })
    },
    fetchAllList() {
      this.loading = true
      this.$api.homeRanking({
        partnerNo: this.partnerNo,
        type: 'ALL',
        partnerId: this.partnerId
      }).then(res => {
        this.allList = res.data || []
        this.loading = false
      }).catch(() => {
        this.allList = []
        this.loading = false
      })
    },
    initWebSocket() {
      const wsUrl = getWsUrl(WS_KEYS.MARKET)
      if (!wsUrl) return

      this.wsConnection = connect(wsUrl, (data) => {
        if (data && data.symbol) {
          const idx = this.allList.findIndex(item => item.symbol === data.symbol)
          if (idx > -1) {
            this.$set(this.allList, idx, { ...this.allList[idx], ...data })
          }
          this.dynamicZones.forEach(zone => {
            const zIdx = zone.list.findIndex(item => item.symbol === data.symbol)
            if (zIdx > -1) {
              this.$set(zone.list, zIdx, { ...zone.list[zIdx], ...data })
            }
          })
        }
      })
    }
  }
}
</script>

