{"content": "<!-- 行情列表组件 -->
<template>
  <div class="market-list">
    <van-loading v-if="loading" class="loading" />
    <div v-else-if="!data || data.length === 0" class="empty">
      <van-empty description="暂无数据" />
    </div>
    <van-cell-group v-else>
      <van-cell
        v-for="item in data"
        :key="item.symbol || item.tradeName"
        :title="`${item.sellSymbol}/${item.buySymbol}`"
        :label="item.tradeName"
        is-link
        @click="goToDetail(item)"
      >
        <template #right-icon>
          <div class="price-info">
            <div :class="['price', item.chg > 0 ? 'up' : item.chg < 0 ? 'down' : '']">
              {{ formatPrice(item.last) }}
            </div>
            <div :class="['change', item.chg > 0 ? 'up' : item.chg < 0 ? 'down' : '']">
              {{ item.chg > 0 ? '+' : '' }}{{ formatChange(item.chg) }}%
            </div>
          </div>
          <van-icon
            :name="isFavorite(item) ? 'star' : 'star-o'"
            :color="isFavorite(item) ? '#ee0a24' : '#969799'"
            class="favorite-icon"
            @click.stop="toggleFavorite(item)"
          />
        </template>
      </van-cell>
    </van-cell-group>
  </div>
</template>

<script>
export default {
  name: 'MarketList',
  props: {
    data: {
      type: Array,
      default: () => []
    },
    loading: {
      type: Boolean,
      default: false
    }
  },
  computed: {
    favorites() {
      try {
        return JSON.parse(localStorage.getItem('market_favorites') || '[]')
      } catch {
        return []
      }
    }
  },
  methods: {
    formatPrice(price) {
      if (!price && price !== 0) return '--'
      const num = parseFloat(price)
      if (num >= 1) return num.toFixed(2)
      if (num >= 0.01) return num.toFixed(4)
      return num.toFixed(8)
    },
    formatChange(chg) {
      if (!chg && chg !== 0) return '--'
      return parseFloat(chg).toFixed(2)
    },
    isFavorite(item) {
      const symbol = item.symbol || item.tradeName
      return this.favorites.includes(symbol)
    },
    toggleFavorite(item) {
      const symbol = item.symbol || item.tradeName
      this.$emit('toggle-favorite', symbol)
    },
    goToDetail(item) {
      this.$router.push({
        name: 'TradeLine',
        query: {
          symbol: item.symbol || item.tradeName,
          sellSymbol: item.sellSymbol,
          buySymbol: item.buySymbol
        }
      })
    }
  }
}
</script>

<style scoped>
.market-list {
  padding: 0;
}

.loading {
  padding: 40px 0;
  text-align: center;
}

.empty {
  padding: 60px 0;
}

.price-info {
  text-align: right;
  margin-right: 8px;
}

.price {
  font-size: 14px;
  font-weight: 500;
}

.change {
  font-size: 12px;
  margin-top: 2px;
}

.up {
  color: #07c160;
}

.down {
  color: #ee0a24;
}

.favorite-icon {
  font-size: 20px;
  margin-left: 8px;
}
</style>
