});

router.beforeEach((to, from, next) => {
  const {
    user: { isLogin },
  } = store.state;
  if (isLogin) {
    // 存在currentUser
    if (to.name === "login") {
      // 显式语言登录入口：允许停留在登录页，不强制跳首页
      if (to.query && to.query.language) {
        next();
        return;
      }
      // 已登录访问 login：优先按 redirect/direct 直达
      const redirectTarget =
        (to.query && (to.query.redirect || to.query.direct)) || "";
      if (redirectTarget) {
        let decodedTarget = redirectTarget;
        try {
          decodedTarget = decodeURIComponent(redirectTarget);
        } catch (e) {
          decodedTarget = redirectTarget;
        }
        if (/^https?:\/\//i.test(decodedTarget)) {
          window.location.href = decodedTarget;
          return;
        }
        next(decodedTarget);
        return;
      }
      // 访问login页面,跳转 index 页面
      next({ path: "/index" });
    } else {
      next();
    }
  } else {
    // 不存在currentUser
    const whiteList = [
      "login",
      "register",
      "forgotPassword",
      "setPassword",
      "agreement",
      "privacyPolicy",
      "resetPassword",
      "index",
      "home",
      "newOption",
      "userCenter",
      "settings",
      "serve",
      "IEO",
      "IEOdetails",
      "details",
      "LockUp",
      "rules",
      "guide",
      "news",
      "newsContent",
      "newToken",
      "TradeCenter",
      "TradeLine",
      "lockUpAd",
      "contract",
      "contracTradeLine",
      "luckyBlindBox",
      "rwa",
      "rwaDetail",
    ];
    if (whiteList.indexOf(to.name) > -1) {
      // 访问白名单页面，则进行默认行为
      next();
    } else {
      // 访问其他页面,则跳转到login页面
      next({
        path: "/login",
        query: { redirect: encodeURIComponent(to.fullPath) },
      });
    }
  }
});

export default router;
