      if (to.query && to.query.language) {
        next();
        return;
      }
      // 已登录访问 login：优先按 redirect/direct 直达
      const redirectTarget =
        (to.query && (to.query.redirect || to.query.direct)) || "";
      if (redirectTarget) {
        let decodedTarget = redirectTarget;
        try {
          decodedTarget = decodeURIComponent(redirectTarget);
        } catch (e) {
          decodedTarget = redirectTarget;
        }
        if (/^https?:\/\//i.test(decodedTarget)) {
          window.location.href = decodedTarget;
          return;
        }
        next(decodedTarget);
        return;
      }
      // 访问login页面,跳转 index 页面
      next({ path: "/index" });
    } else {
      next();
    }
  } else {
