from __future__ import annotations
"""Shared Lark authentication module.

Extracted from collector.py and reporter.py to eliminate duplication.
"""

import json
import os
import subprocess
from pathlib import Path

LARK_MCP_ROOT = "/Users/charles/.nvm/versions/node/v24.14.0/lib/node_modules/@larksuiteoapi/lark-mcp"

_SCRIPT_TEMPLATE = f"""
const {{ authStore }} = require('{LARK_MCP_ROOT}/dist/auth/store.js');
authStore.initialize().then(() => {{
  const tokens = authStore.storageDataCache.tokens || {{}};
  const keys = Object.keys(tokens);
  if (!keys.length) {{ process.stderr.write('NO_TOKEN\\n'); process.exit(1); }}
  const token = keys[0];
  const meta = tokens[token];
  if (Date.now() / 1000 > meta.expiresAt) {{ process.stderr.write('TOKEN_EXPIRED\\n'); process.exit(1); }}
  process.stdout.write(token);
  process.exit(0);
}}).catch(e => {{ process.stderr.write(String(e)); process.exit(1); }});
"""


def get_token() -> str:
    """Read user_access_token from lark-mcp storage. Auto-refresh if expired."""
    result = subprocess.run(
        ["node", "-e", _SCRIPT_TEMPLATE],
        capture_output=True, text=True, timeout=15
    )

    # Token 过期 → 尝试自动刷新
    if result.returncode != 0 and "TOKEN_EXPIRED" in result.stderr:
        print("[lark_auth] Token expired, attempting refresh...")
        refresh_result = subprocess.run(
            ["npx", "@larksuiteoapi/lark-mcp", "login",
             "--app-id", os.environ.get("LARK_APP_ID", ""),
             "--app-secret", os.environ.get("LARK_APP_SECRET", ""),
             "--domain", "https://open.larksuite.com"],
            capture_output=True, text=True, timeout=60
        )
        if refresh_result.returncode == 0:
            result = subprocess.run(
                ["node", "-e", _SCRIPT_TEMPLATE],
                capture_output=True, text=True, timeout=15
            )
        else:
            raise RuntimeError(f"Token refresh failed: {refresh_result.stderr.strip()}")

    if result.returncode != 0:
        raise RuntimeError(f"Token error: {result.stderr.strip()}")
    return result.stdout.strip()
