<template>
  <div class="market-page">
    <van-tabs v-model="activeTab" animated swipeable @change="onTabChange">
      <van-tab v-for="tab in tabs" :key="tab.type" :title="tab.name">
        <MarketList :data="tab.list" :loading="tab.loading" @toggle-favorite="toggleFavorite" />
      </van-tab>
    </van-tabs>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'
import MarketList from './components/MarketList.vue'
import { getWsUrl, WS_KEYS } from '@/utils/websocketUrls'
import { connect } from '@/utils/websocketManager'

const FAVORITES_KEY = 'market_favorites'

// 1:1 对齐 Android 端的 tab 结构
const TAB_CONFIG = [
  { type: 'POPULAR_RANKING', name: '热门', list: [], loading: true },
  { type: 'GO_UP_RANKING', name: '涨幅', list: [], loading: true },
  { type: 'TO_FALL_RANKING', name: '跌幅', list: [], loading: true },
  { type: 'NEW_COIN_RANKING', name: '新币', list: [], loading: true },
  { type: 'VOL_RANKING', name: '人气', list: [], loading: true },
]

export default {
  name: 'Market',
  components: { MarketList },
  data() {
    return {
      activeTab: 0,
      tabs: TAB_CONFIG.map(t => ({ ...t })),
      favorites: [],
      wsConnection: null,
      wsSend: null,
    }
  },
  computed: {
    ...mapGetters(['partnerId', 'partnerNo', 'currencySymbol']),
  },
  mounted() {
    this.loadFavorites()
    this.fetchExchangeRate()
    this.fetchCurrentTab()
    this.initWebSocket()
  },
  beforeDestroy() {
    this.cancelSubscription()
    if (this.wsConnection) {
      this.wsConnection.close()
    }
  },
  methods: {
    // 加载本地自选
    loadFavorites() {
      try {
        const saved = localStorage.getItem(FAVORITES_KEY)
        this.favorites = saved ? JSON.parse(saved) : []
      } catch {
        this.favorites = []
      }
    },
    // 保存自选
    saveFavorites() {
      localStorage.setItem(FAVORITES_KEY, JSON.stringify(this.favorites))
    },
    // 切换自选
    toggleFavorite(symbol) {
      const idx = this.favorites.indexOf(symbol)
      if (idx > -1) {
        this.favorites.splice(idx, 1)
      } else {
        this.favorites.push(symbol)
      }
      this.saveFavorites()
    },
    // Tab 切换
    onTabChange(index) {
      this.cancelSubscription()
      this.fetchCurrentTab()
      this.subscription()
    },
    // 获取当前 tab 数据
    fetchCurrentTab() {
      const tab = this.tabs[this.activeTab]
      tab.loading = true

      this.$api.homeRanking({
        partnerNo: this.partnerNo,
        type: tab.type,
        partnerId: this.partnerId,
      }).then(res => {
        tab.list = res.data || []
        tab.loading = false
      }).catch(() => {
        tab.list = []
        tab.loading = false
      })
    },
    // 获取汇率（对齐 Android 端 setCurrenciesConversion）
    fetchExchangeRate() {
      this.$api.tradeAreaPrice_3_0_6({
        partnerId: this.partnerId,
        currency: this.currencySymbol,
      }).then(res => {
        // 存储汇率供子组件使用
        if (res.data && res.data.usd) {
          this.$store.commit('SET_EXCHANGE_RATE', res.data.usd)
        }
      }).catch(() => {})
    },
    // WebSocket 订阅（对齐 Android 端 Subscription）
    initWebSocket() {
      const wsUrl = getWsUrl(WS_KEYS.MARKET)
      if (!wsUrl) return

      this.wsConnection = connect(wsUrl, (data) => {
        if (data && data.symbol) {
          this.updatePrice(data)
        }
      })

      this.subscription()
    },
    // 订阅当前 tab 的实时数据
    subscription() {
      if (!this.wsSend) return

      const tab = this.tabs[this.activeTab]
      const wsTag = this.getWsTag(tab.type)

      this.wsSend(JSON.stringify({
        tag: 'sub',
        content: wsTag,
      }))
    },
    // 取消订阅
    cancelSubscription() {
      if (!this.wsSend) return

      const tab = this.tabs[this.activeTab]
      const wsTag = this.getWsTag(tab.type)

      this.wsSend(JSON.stringify({
        tag: 'cancel',
        content: wsTag,
      }))
    },
    // Android 端 WebSocket tag 映射
    getWsTag(type) {
      const tagMap = {
        'POPULAR_RANKING': 'market.0.popular_ranking',
        'GO_UP_RANKING': 'market.0.go_up_ranking',
        'TO_FALL_RANKING': 'market.0.to_fall_ranking',
        'NEW_COIN_RANKING': 'market.0.new_coin_ranking',
        'VOL_RANKING': 'market.0.vol_ranking',
      }
      return tagMap[type] || 'market.0.popular_ranking'
    },
    // 更新价格
    updatePrice(data) {
      const tab = this.tabs[this.activeTab]
      const idx = tab.list.findIndex(item => item.symbol === data.symbol)
      if (idx > -1) {
        this.$set(tab.list, idx, { ...tab.list[idx], ...data })
      }
    },
  }
}
</script>

