        :key="item.symbol || item.sellSymbol"
        class="market-item"
        @click="goToDetail(item)"
      >
        <!-- 币对名称 -->
        <div class="symbol">{{ item.sellSymbol }}/{{ item.buySymbol }}</div>

        <!-- 价格 + 涨跌箭头 -->
        <div class="price-row">
          <span :class="['price', item.chg > 0 ? 'up' : item.chg < 0 ? 'down' : '']">
            {{ formatPrice(item.last) }}
          </span>
          <span class="arrow">
            <van-icon v-if="item.chg > 0" name="arrow-up" color="#07c160" />
            <van-icon v-else-if="item.chg < 0" name="arrow-down" color="#ee0a24" />
          </span>
        </div>

        <!-- 涨跌幅 -->
        <div :class="['change', item.chg > 0 ? 'up' : item.chg < 0 ? 'down' : '']">
          {{ item.chg > 0 ? '+' : '' }}{{ formatChange(item.chg) }}%
        </div>

        <!-- CNY 折算 -->
        <div class="cny-price" v-if="rate">
          ≈ {{ fiatSymbol }}{{ formatCNY(item.last) }}
        </div>

        <!-- 自选按钮 -->
        <van-icon
          :name="isFavorite(item) ? 'star' : 'star-o'"
          :color="isFavorite(item) ? '#ee0a24' : '#969799'"
          class="favorite-btn"
          @click.stop="toggleFavorite(item)"
        />

        <!-- 分割线 -->
        <div class="divider"></div>
      </div>
    </div>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'
import { getFiatSymbol } from '@/utils/fiatSymbol'

export default {
  name: 'MarketList',
  props: {
    data: {
      type: Array,
      default: () => []
    },
    loading: {
      type: Boolean,
      default: false
    }
  },
  computed: {
    ...mapGetters(['currencySymbol']),
    fiatSymbol() {
      return getFiatSymbol(this.currencySymbol)
    },
    rate() {
      // 从 store 获取汇率
      const rates = this.$store.state.exchangeRate || []
      const usdt = rates.find(r => r.coinName === 'USDT')
      return usdt ? parseFloat(usdt.coinPrice) : 1
    },
    favorites() {
      try {
        return JSON.parse(localStorage.getItem('market_favorites') || '[]')
      } catch {
        return []
      }
    }
  },
  methods: {
    formatPrice(price) {
      if (!price && price !== 0) return '--'
      const num = parseFloat(price)
      if (num >= 1) return num.toFixed(2)
      if (num >= 0.01) return num.toFixed(4)
      return num.toFixed(8)
    },
    formatChange(chg) {
      if (!chg && chg !== 0) return '--'
      return parseFloat(chg).toFixed(2)
    },
    formatCNY(price) {
      if (!price || !this.rate) return '--'
      const cny = parseFloat(price) * this.rate
      if (cny >= 1) return cny.toFixed(2)
      return cny.toFixed(4)
    },
    isFavorite(item) {
      const symbol = item.symbol || `${item.sellSymbol}${item.buySymbol}`
      return this.favorites.includes(symbol)
    },
    toggleFavorite(item) {
      const symbol = item.symbol || `${item.sellSymbol}${item.buySymbol}`
      this.$emit('toggle-favorite', symbol)
    },
    goToDetail(item) {
      this.$router.push({
        name: 'TradeLine',
        query: {
          symbol: item.symbol || `${item.sellSymbol}${item.buySymbol}`,
          sellSymbol: item.sellSymbol,
          buySymbol: item.buySymbol
        }
      })
    }
  }
}
</script>

