{"content": "#!/usr/bin/env python3
from __future__ import annotations
"""Design analysis module: extract requirements from screenshots and design links."""

import os
import subprocess
import re
from pathlib import Path

HERMES_CMD = os.environ.get("ARC_HERMES_CMD", "hermes")


def extract_links_from_text(text: str) -> list[str]:
    """Extract URLs from text."""
    return re.findall(r'https?://[^\s\]"]+', text)


def is_figma_link(url: str) -> bool:
    """Check if URL is a Figma design link."""
    return "figma.com" in url.lower()


def is_screenshot_link(url: str) -> bool:
    """Check if URL is an image/screenshot link."""
    image_exts = ['.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg', '.bmp']
    url_lower = url.lower()
    return any(url_lower.endswith(ext) for ext in image_exts) or \
           any(domain in url_lower for domain in ['img.', 'image.', 'cdn.', 'oss.', 'lark.'])


def analyze_design_link(url: str, dry_run: bool = False) -> str:
    """
    Analyze a design link (Figma/screenshot) and extract requirements.

    Returns:
        Description of the design requirements
    """
    if dry_run:
        return f"[DRY] Would analyze: {url}"

    if is_figma_link(url):
        return analyze_figma(url)
    elif is_screenshot_link(url):
        return analyze_screenshot(url)
    else:
        return f"链接: {url}\n类型: 未知，可能需要人工查看"


def analyze_figma(url: str) -> str:
    """Analyze Figma design link."""
    # Figma 需要特殊处理，这里简化为提示
    return (
        f"Figma 设计稿: {url}\n"
        f"提示: Figma 设计稿需要人工查看或使用 Figma MCP 工具提取"
    )


def analyze_screenshot(url: str) -> str:
    """Analyze screenshot using hermes browser vision."""
    cmd = [
        HERMES_CMD, "chat", "-q",
        f"打开这个图片链接 {url}，分析页面布局、元素、颜色、间距，输出结构化描述。不要做其他操作。",
        "--toolsets", "browser",
    ]

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=60,
            env={**os.environ, "HERMES_NO_BANNER": "1"},
        )
        if result.returncode == 0:
            return result.stdout.strip()[:500]
        return f"分析失败: {result.stderr[:100]}"
    except Exception as e:
        return f"分析错误: {e}"


def enrich_comments_with_design_analysis(comments_text: str, dry_run: bool = False) -> str:
    """
    Analyze links in comments and append design requirements.

    Returns:
        Enriched comments text with design analysis
    """
    links = extract_links_from_text(comments_text)
    if not links:
        return comments_text

    analysis_parts = []
    for link in links[:3]:  # 最多分析 3 个链接
        if is_figma_link(link) or is_screenshot_link(link):
            analysis = analyze_design_link(link, dry_run=dry_run)
            analysis_parts.append(f"### 链接分析: {link}\n{analysis}")

    if analysis_parts:
        return comments_text + "\n\n## 设计稿分析\n" + "\n\n".join(analysis_parts)

    return comments_text
