from __future__ import annotations
"""Deployment module: git push → CI → deploy → notify."""

import os
import subprocess
import json
from pathlib import Path


def git_add_commit_push(
    project_path: str,
    message: str,
    files: list[str] = None,
    dry_run: bool = False
) -> dict:
    """
    Git add, commit, and push.

    Returns:
        {"success": bool, "commit_hash": str, "error": str}
    """
    if dry_run:
        return {"success": True, "commit_hash": "dry-run", "error": None}

    try:
        # git add
        if files:
            for f in files:
                subprocess.run(["git", "add", f], cwd=project_path, check=True, capture_output=True)
        else:
            subprocess.run(["git", "add", "-A"], cwd=project_path, check=True, capture_output=True)

        # git commit
        result = subprocess.run(
            ["git", "commit", "-m", message],
            cwd=project_path,
            capture_output=True,
            text=True,
        )

        if result.returncode != 0 and "nothing to commit" in result.stderr:
            return {"success": True, "commit_hash": None, "error": "nothing to commit"}

        # 获取 commit hash
        hash_result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=project_path,
            capture_output=True,
            text=True,
        )
        commit_hash = hash_result.stdout.strip()[:8] if hash_result.returncode == 0 else "unknown"

        # git push
        push_result = subprocess.run(
            ["git", "push"],
            cwd=project_path,
            capture_output=True,
            text=True,
            timeout=60,
        )

        if push_result.returncode != 0:
            return {
                "success": False,
                "commit_hash": commit_hash,
                "error": f"push failed: {push_result.stderr[:200]}"
            }

        return {"success": True, "commit_hash": commit_hash, "error": None}

    except subprocess.CalledProcessError as e:
        return {"success": False, "commit_hash": None, "error": str(e)}
    except Exception as e:
        return {"success": False, "commit_hash": None, "error": str(e)}


def check_ci_status(project_path: str, commit_hash: str, dry_run: bool = False) -> dict:
    """
    Check CI build status for a commit.

    Returns:
        {"success": bool, "status": str, "url": str}
    """
    if dry_run:
        return {"success": True, "status": "passed", "url": ""}

    try:
        # 检查是否有 GitHub Actions
        result = subprocess.run(
            ["gh", "run", "list", "--limit", "1", "--json", "status,conclusion,url"],
            cwd=project_path,
            capture_output=True,
            text=True,
            timeout=30,
        )

        if result.returncode == 0:
            runs = json.loads(result.stdout)
            if runs:
                run = runs[0]
                return {
                    "success": run.get("conclusion") == "success",
                    "status": run.get("status", "unknown"),
                    "url": run.get("url", ""),
                }

        return {"success": True, "status": "no-ci", "url": ""}
    except Exception:
        return {"success": True, "status": "check-failed", "url": ""}


def deploy(project_path: str, dry_run: bool = False) -> dict:
    """
    Deploy the project (platform-specific).

    Returns:
        {"success": bool, "url": str, "error": str}
    """
    if dry_run:
        return {"success": True, "url": "https://dry-run.pages.dev", "error": None}

    # 检测部署平台
    wrangler_toml = Path(project_path) / "wrangler.toml"
    netlify_toml = Path(project_path) / "netlify.toml"
    vercel_json = Path(project_path) / "vercel.json"

    if wrangler_toml.is_file():
        return deploy_cloudflare(project_path)
    elif netlify_toml.is_file():
        return deploy_netlify(project_path)
    elif vercel_json.is_file():
        return deploy_vercel(project_path)
    else:
        return {"success": False, "url": "", "error": "no deploy platform detected"}


def deploy_cloudflare(project_path: str) -> dict:
    """Deploy to Cloudflare Pages."""
    try:
        result = subprocess.run(
            ["npx", "wrangler", "pages", "deploy"],
            cwd=project_path,
            capture_output=True,
            text=True,
            timeout=180,
        )

        if result.returncode == 0:
            # 提取部署 URL
            import re
            url_match = re.search(r'https://[^\s]+\.pages\.dev', result.stdout)
            url = url_match.group(0) if url_match else ""
            return {"success": True, "url": url, "error": None}
        return {"success": False, "url": "", "error": result.stderr[:200]}
    except Exception as e:
        return {"success": False, "url": "", "error": str(e)}


def deploy_netlify(project_path: str) -> dict:
    """Deploy to Netlify."""
    try:
        result = subprocess.run(
            ["npx", "netlify", "deploy", "--prod"],
            cwd=project_path,
            capture_output=True,
            text=True,
            timeout=180,
        )
        return {"success": result.returncode == 0, "url": "", "error": result.stderr[:200] if result.returncode != 0 else None}
    except Exception as e:
        return {"success": False, "url": "", "error": str(e)}


def deploy_vercel(project_path: str) -> dict:
    """Deploy to Vercel."""
    try:
        result = subprocess.run(
            ["npx", "vercel", "--prod", "--yes"],
            cwd=project_path,
            capture_output=True,
            text=True,
