{"content": "#!/usr/bin/env python3
from __future__ import annotations
"""Feedback module: user confirmation and auto-fix loop."""

import os
import subprocess
import json
from pathlib import Path

HERMES_CMD = os.environ.get("ARC_HERMES_CMD", "hermes")


def ask_user_confirmation(
    task_summary: str,
    project_id: str,
    screenshot_path: str = None,
    deploy_url: str = None,
    dry_run: bool = False,
) -> dict:
    """
    Ask user to confirm task completion.

    Returns:
        {"confirmed": bool, "feedback": str, "action": "close|retry|skip"}
    """
    if dry_run:
        return {"confirmed": True, "feedback": "dry run", "action": "close"}

    message = f"任务完成确认\n\n"
    message += f"任务: {task_summary}\n"
    message += f"项目: {project_id}\n"

    if screenshot_path:
        message += f"截图: {screenshot_path}\n"

    if deploy_url:
        message += f"部署链接: {deploy_url}\n"

    message += "\n请确认: 关闭/重试/跳过"

    cmd = [
        HERMES_CMD, "chat", "-q",
        f"询问用户确认: {message}",
        "--toolsets", "messaging",
    ]

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=300,  # 等待用户 5 分钟
            env={**os.environ, "HERMES_NO_BANNER": "1"},
        )

        output = result.stdout.strip().lower()

        if "close" in output or "完成" in output or "ok" in output:
            return {"confirmed": True, "feedback": output, "action": "close"}
        elif "retry" in output or "重试" in output:
            return {"confirmed": False, "feedback": output, "action": "retry"}
        elif "skip" in output or "跳过" in output:
            return {"confirmed": True, "feedback": output, "action": "skip"}
        else:
            return {"confirmed": False, "feedback": output, "action": "retry"}

    except subprocess.TimeoutExpired:
        return {"confirmed": True, "feedback": "timeout, auto-close", "action": "close"}
    except Exception as e:
        return {"confirmed": True, "feedback": str(e), "action": "close"}


def auto_fix_loop(
    envelope: dict,
    error_message: str,
    max_attempts: int = 2,
    dry_run: bool = False,
) -> dict:
    """
    Auto-fix loop: try to fix issues automatically.

    Returns:
        {"success": bool, "attempts": int, "final_error": str}
    """
    if dry_run:
        return {"success": True, "attempts": 0, "final_error": None}

    eid = envelope["id"]
    project_path = envelope["project"]
    summary = envelope["payload"].get("summary", "")

    for attempt in range(max_attempts):
        print(f"  [AUTO-FIX] attempt {attempt + 1}/{max_attempts}")

        fix_prompt = (
            f"修复以下问题:\n"
            f"任务: {summary}\n"
            f"错误: {error_message}\n"
            f"项目路径: {project_path}\n"
            f"\n"
            f"请分析错误原因并修复。修复后运行构建验证。"
        )

        cmd = [
            HERMES_CMD, "chat", "-q", fix_prompt,
            "--toolsets", "terminal,file",
        ]

        try:
            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                cwd=project_path,
                timeout=300,
                env={**os.environ, "HERMES_NO_BANNER": "1"},
            )

            if result.returncode == 0:
                # 验证构建
                build_cmd = subprocess.run(
                    ["npm", "run", "build"],
                    cwd=project_path,
                    capture_output=True,
                    text=True,
                    timeout=120,
                )

                if build_cmd.returncode == 0:
                    return {"success": True, "attempts": attempt + 1, "final_error": None}

        except Exception as e:
            print(f"  [AUTO-FIX ERROR] {e}")

    return {"success": False, "attempts": max_attempts, "final_error": error_message}
